// 実行日が営業日か確認（祝日チェックは将来実装）
const now = new Date();
const day = now.getDay();
// 0=日曜, 6=土曜
if (day === 0 || day === 6) {
  throw new Error('土日のため実行をスキップします');
}
return [{ json: { date: now.toISOString(), weekday: day } }];

